 interface Gateway { boolean approved(int amount); }
 static String pay(Gateway gateway, int amount) {
  return gateway.approved(amount) ? "PAID" : "DECLINED";
 }
 public static void main(String[] args) {
  Gateway declining = amount -> false;
  if (!"DECLINED".equals(pay(declining, 100))) throw new AssertionError();
 }
}

