public class ExceptionDemo {
 static int parseAge(String text) {
  int age = Integer.parseInt(text);
  if (age < 0) throw new IllegalArgumentException("age must be nonnegative");
  return age;
 }
 public static void main(String[] args) {
  try { System.out.println(parseAge("-1")); }
  catch (IllegalArgumentException error) { System.out.println(error.getMessage()); }
 }
}

lessons.qacode:
public class QaException {
 public static void main(String[] args) {
  try {
   ExceptionDemo.parseAge("-1");
   throw new AssertionError("Expected rejection");
  } catch (IllegalArgumentException expected) {
   if (!expected.getMessage().contains("nonnegative")) throw new AssertionError();
  }
 }
}

