import java.util.*;
public class CollectionsDemo {
 public static void main(String[] args) {
  List cities = new ArrayList<>(List.of("Oslo", "Bergen", "Oslo"));
  Set unique = new LinkedHashSet<>(cities);
  Map counts = new LinkedHashMap<>();
  for (String city : cities) counts.merge(city, 1, Integer::sum);
  System.out.println(unique);
  System.out.println(counts);
 }
}

