import java.time.*;
public class QaClock {
 static boolean expired(Instant expires, Clock clock) {
  return !Instant.now(clock).isBefore(expires);
 }
 public static void main(String[] args) {
  Instant deadline = Instant.parse("2026-09-27T10:00:00Z");
  Clock fixed = Clock.fixed(deadline, ZoneOffset.UTC);
  if (!expired(deadline, fixed)) throw new AssertionError("Boundary");
 }
}

