import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.net.http.*;
public class QaHttp {
 public static void main(String[] args) throws Exception {
  var server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
  server.createContext("/health", exchange -> {
   byte[] body = "UP".getBytes(java.nio.charset.StandardCharsets.UTF_8);
   exchange.sendResponseHeaders(200, body.length);
   try(var out = exchange.getResponseBody()) { out.write(body); }
  });
  server.start();
  try {
   var uri = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/health");
   var response = HttpClient.newHttpClient().send(
    HttpRequest.newBuilder(uri).GET().build(), HttpResponse.BodyHandlers.ofString());
   if(response.statusCode()!=200 || !response.body().equals("UP")) throw new AssertionError();
  } finally { server.stop(0); }
 }
}

