public class PaymentFlow {
 interface Gateway { String charge(String key, int amount); }
 static class Service {
  private final Gateway gateway;
  Service(Gateway gateway) { this.gateway = gateway; }
  String pay(String key, int amount) {
   if(key == null || key.isBlank() || amount <= 0) throw new IllegalArgumentException();
   return gateway.charge(key, amount);
  }
 }
 public static void main(String[] args) {
  Service service = new Service((key, amount) -> "APPROVED");
  System.out.println(service.pay("order-42", 100));
 }
}

